      title: '住宿的"住"用 묵다 不用 살다',
      detail: '短期住宿、过夜用 묵다（투숙）。살다 是"长期居住/生活"，说 여기서 삼 일 살아요 会让人以为你要在这定居 —— 旅行住几晚一律用 묵다.',
